```json
{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "Comparison of feature profiles between Brás and the most similar Chicago areas",
  "params": [
    {
      "name": "clickSelect",
      "select": "interval"
    }
  ],
  "transform": [
    {
      "fold": [
        "poverty_rate",
        "unemployment_rate",
        "median_income",
        "edu_low",
        "minority_pct",
        "housing_burden",
        "crash_rate",
        "pop_density",
        "transit_access",
        "access_score"
      ],
      "as": ["Feature", "Value"]
    }
  ],
  "mark": {
    "type": "point",
    "cursor": "pointer",
    "size": 100
  },
  "encoding": {
    "x": {
      "field": "Feature",
      "type": "nominal",
      "axis": {"labelAngle": -45}
    },
    "y": {
      "field": "Value",
      "type": "quantitative"
    },
    "color": {
      "field": "area_name",
      "type": "nominal",
      "scale": {"scheme": "category10"},
      "legend": {"title": "Community Area"}
    },
    "opacity": {
      "condition": {"param": "clickSelect", "value": 1},
      "value": 0.3
    },
    "shape": {
      "condition": {
        "test": "datum.area_name === 'Brás'",
        "value": "diamond"
      },
      "value": "circle"
    },
    "tooltip": [
      {"field": "area_name", "type": "nominal", "title": "Area"},
      {"field": "Feature", "type": "nominal"},
      {"field": "Value", "type": "quantitative"}
    ]
  }
}
```
